"use client";

import { useEffect, useId, useRef, useState, type ComponentProps } from "react";

import { IconAlertCircle, IconCheck, IconChevronDown, IconCopy, IconExternal, IconNavigation } from "@rhs-ui/icons";
import {
  APP_NAMES,
  appsForMode,
  buildDirectionsUrl,
  copyTextOf,
  copyToClipboard,
  orderApps,
  placeProblem,
  prefersAppleMaps,
  type DirectionsApp,
  type DirectionsPlace,
  type TravelMode,
} from "@rhs-ui/application/directions-button/directions";
import { Button, type ButtonProps } from "@rhs-ui/primitives/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@rhs-ui/primitives/dropdown-menu";
import { cn } from "@/lib/utils";

export interface DirectionsButtonProps extends Omit<ComponentProps<"div">, "children"> {
  /** The place to go to: an address (with its name, so the pin is labelled) or latitude and longitude. */
  destination: DirectionsPlace;
  /** Where the route starts. Leave it out to start from the person's own position. */
  origin?: DirectionsPlace;
  /** How they travel. Waze only drives, so it is left out for the other modes. Default "driving". */
  mode?: TravelMode;
  /** The apps to offer, in order of preference. Without it: Apple Maps first on iPhone and iPad, Google Maps first everywhere else. */
  apps?: readonly DirectionsApp[];
  /** The button's text. Default "Get directions". */
  label?: string;
  /** Called when a maps link is opened, with the app. */
  onOpen?: (app: DirectionsApp) => void;
  /** Any Button variant. Default "outline". */
  variant?: ButtonProps["variant"];
  /** Any Button size. */
  size?: ButtonProps["size"];
}

type CopyState = "idle" | "copied" | "failed";

const TILE: Record<DirectionsApp, string> = { apple: "A", google: "G", waze: "W" };
// The divider between two solid buttons, where there is no shared border to draw it.
const DIVIDER: Partial<Record<NonNullable<ButtonProps["variant"]>, string>> = {
  default: "border-l-primary-foreground/30",
  secondary: "border-l-foreground/15",
  destructive: "border-l-destructive-foreground/30",
};

function AppRow({ app }: { app: DirectionsApp }) {
  return (
    <>
      <span aria-hidden="true" className="grid size-8 shrink-0 place-items-center rounded-md border border-border bg-muted/60 text-xs font-semibold text-foreground">
        {TILE[app]}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-sm leading-tight font-medium text-foreground">{APP_NAMES[app]}</span>
        <span className="mt-0.5 block text-xs text-muted-foreground">Opens in a new tab</span>
      </span>
      <IconExternal className="size-3.5" />
    </>
  );
}

/**
 * A button that hands a place to a maps app. The main button is a real link
 * to the app people use: Apple Maps on an iPhone or iPad, Google Maps
 * everywhere else, worked out after the page has loaded so server and browser
 * markup agree. A small chevron opens the other apps and "Copy address". The
 * place's name goes into the query, so the pin is labelled; links are built
 * by exported pure functions with proper encoding. Every external link says it
 * opens a new tab, and a place without an address or coordinates disables the
 * button and says why.
 */
export function DirectionsButton({ destination, origin, mode = "driving", apps, label = "Get directions", onOpen, variant = "outline", size, className, ...props }: DirectionsButtonProps) {
  const reasonId = useId();
  const [apple, setApple] = useState(false);
  const [open, setOpen] = useState(false);
  const [placement, setPlacement] = useState<{ align: "start" | "end"; offset: number }>({ align: "end", offset: 0 });
  const group = useRef<HTMLDivElement>(null);
  const chevron = useRef<HTMLButtonElement>(null);
  const [copy, setCopy] = useState<CopyState>("idle");
  const timers = useRef<number[]>([]);

  // Whether this is an iPhone or iPad is only known in the browser, so it is worked out after mount and the server and the first render agree.
  useEffect(() => {
    setApple(prefersAppleMaps({ userAgent: navigator.userAgent, platform: navigator.platform, maxTouchPoints: navigator.maxTouchPoints }));
    // Read at cleanup time on purpose: the list is replaced every time a copy starts.
    return () => timers.current.forEach((timer) => window.clearTimeout(timer));
  }, []);

  const offered = appsForMode(orderApps(apps, apple), mode);
  const problem = placeProblem(destination) ?? (offered.length ? null : "None of these apps give directions for this way of travelling.");
  const [first, ...others] = offered;
  const options = { origin, mode };
  const primaryHref = first && !problem ? buildDirectionsUrl(first, destination, options) : null;
  const copyText = copyTextOf(destination);
  const chevronSize = size === "sm" ? "icon-sm" : "icon";

  // The menu lines up with the whole control, not just the chevron: its left edge in the left half of the screen, its right edge in the right half.
  function changeOpen(next: boolean) {
    const box = group.current?.getBoundingClientRect();
    const trigger = chevron.current?.getBoundingClientRect();
    if (next && box && trigger) setPlacement(box.left + box.width / 2 > window.innerWidth / 2 ? { align: "end", offset: 0 } : { align: "start", offset: box.left - trigger.left });
    setOpen(next);
  }

  async function copyAddress() {
    if (!copyText) return;
    timers.current.forEach((timer) => window.clearTimeout(timer));
    const done = await copyToClipboard(copyText);
    setCopy(done ? "copied" : "failed");
    // The result shows in the menu for a moment, then the menu folds away.
    timers.current = [window.setTimeout(() => setOpen(false), done ? 900 : 1600), window.setTimeout(() => setCopy("idle"), done ? 1400 : 2100)];
  }

  const joinLeft = "min-w-0 shrink rounded-r-none hover:z-[1] focus-visible:z-10";
  const joinRight = cn("-ml-px rounded-l-none hover:z-[1] focus-visible:z-10", size === "lg" && "size-11", DIVIDER[variant ?? "outline"]);

  return (
    <div data-slot="directions-button" className={cn("inline-flex max-w-full flex-col items-start gap-1.5", className)} {...props}>
      <span role="status" className="sr-only">
        {copy === "copied" ? "Address copied" : copy === "failed" ? "Could not copy the address" : ""}
      </span>
      {primaryHref && first ? (
        <div ref={group} role="group" aria-label={label} className="inline-flex max-w-full items-stretch">
          <Button asChild variant={variant} size={size} className={joinLeft}>
            <a href={primaryHref} target="_blank" rel="noopener noreferrer" title={`Opens ${APP_NAMES[first]} in a new tab`} onClick={() => onOpen?.(first)}>
              <IconNavigation />
              <span className="truncate">{label}</span>
              <span className="sr-only">
                {" "}
                in {APP_NAMES[first]}, opens in a new tab
              </span>
            </a>
          </Button>
          <DropdownMenu open={open} onOpenChange={changeOpen}>
            <DropdownMenuTrigger asChild>
              <Button ref={chevron} type="button" variant={variant} size={chevronSize} aria-label="More ways to get directions" className={joinRight}>
                <IconChevronDown className="transition-transform duration-200 group-data-[state=open]/button:rotate-180 motion-reduce:transition-none" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align={placement.align} alignOffset={placement.offset} collisionPadding={8} className="w-72 max-w-[calc(100vw-2rem)]">
              {others.length ? <DropdownMenuLabel>Also open in</DropdownMenuLabel> : null}
              {others.map((app) => {
                const href = buildDirectionsUrl(app, destination, options);
                return href ? (
                  <DropdownMenuItem key={app} asChild className="gap-3 py-2">
                    <a href={href} target="_blank" rel="noopener noreferrer" onClick={() => onOpen?.(app)}>
                      <AppRow app={app} />
                    </a>
                  </DropdownMenuItem>
                ) : null;
              })}
              {others.length && copyText ? <DropdownMenuSeparator /> : null}
              {copyText ? (
                <DropdownMenuItem
                  className="gap-3 py-2"
                  onSelect={(event) => {
                    // Stay open: the item says what happened, then the menu closes by itself.
                    event.preventDefault();
                    void copyAddress();
                  }}
                >
                  <span aria-hidden="true" className="grid size-8 shrink-0 place-items-center rounded-md border border-border bg-muted/60">
                    {copy === "copied" ? <IconCheck className="size-4 text-foreground" /> : copy === "failed" ? <IconAlertCircle className="size-4 text-destructive" /> : <IconCopy className="size-4" />}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block text-sm leading-tight font-medium text-foreground">
                      {copy === "copied" ? "Copied" : copy === "failed" ? "Could not copy" : destination.address?.trim() ? "Copy address" : "Copy coordinates"}
                    </span>
                    <span className="mt-0.5 block truncate text-xs text-muted-foreground">{copyText}</span>
                  </span>
                </DropdownMenuItem>
              ) : null}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      ) : (
        <>
          <Button type="button" variant={variant} size={size} disabled aria-describedby={reasonId} className="max-w-full">
            <IconNavigation />
            <span className="truncate">{label}</span>
          </Button>
          <p id={reasonId} className="text-xs text-muted-foreground">
            {problem}
          </p>
        </>
      )}
    </div>
  );
}

/*
 * The pure half of the directions button: a place in, a link for each maps app
 * out, with every part properly encoded. Nothing here touches the page, so the
 * builders can be tested with plain inputs. The button in index.tsx decides
 * which app comes first and what to show.
 */

export type DirectionsApp = "apple" | "google" | "waze";
export type TravelMode = "driving" | "walking" | "cycling" | "transit";

export interface DirectionsPlace {
  /** What the place is called. It goes into the query, so the pin is labelled with it. */
  name?: string;
  /** The street address, as people write it. */
  address?: string;
  /** Exact position, when you have it and no address. */
  latitude?: number;
  /** Exact position, when you have it and no address. */
  longitude?: number;
}

export interface DirectionsOptions {
  /** Where the route starts. Leave it out to start from the person's own position. */
  origin?: DirectionsPlace;
  /** How they travel. Default "driving". */
  mode?: TravelMode;
}

export const APP_NAMES: Record<DirectionsApp, string> = { apple: "Apple Maps", google: "Google Maps", waze: "Waze" };

const validLatitude = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value) && value >= -90 && value <= 90;
const validLongitude = (value: unknown): value is number => typeof value === "number" && Number.isFinite(value) && value >= -180 && value <= 180;

/** "52.370216,4.895168", or null when the place has no valid coordinates. */
export function coordinatesOf(place: DirectionsPlace): string | null {
  if (!validLatitude(place.latitude) || !validLongitude(place.longitude)) return null;
  return `${Number(place.latitude.toFixed(6))},${Number(place.longitude.toFixed(6))}`;
}

/**
 * The text a maps app searches for. With an address it is the name and the
 * address together ("Kestrel Coffee, 12 Prinsengracht, Amsterdam"), which is
 * what makes the pin carry the place's name; without one, the coordinates.
 */
export function placeQuery(place: DirectionsPlace): string | null {
  const address = place.address?.trim();
  if (address) {
    const name = place.name?.trim();
    // A name the address already contains is not said twice.
    return name && !address.toLowerCase().includes(name.toLowerCase()) ? `${name}, ${address}` : address;
  }
  return coordinatesOf(place);
}

/** Why a place cannot be used, in words, or null when it can. A name alone is not enough to route to. */
export function placeProblem(place: DirectionsPlace): string | null {
  if (placeQuery(place)) return null;
  const hasCoordinates = place.latitude !== undefined || place.longitude !== undefined;
  return hasCoordinates ? "The coordinates are not valid." : "Add an address or coordinates to get directions.";
}

/** What "Copy address" copies: the address, or the coordinates when there is none. */
export function copyTextOf(place: DirectionsPlace): string | null {
  const address = place.address?.trim();
  if (address) return address;
  const coordinates = coordinatesOf(place);
  return coordinates ? coordinates.replace(",", ", ") : null;
}

/** Waze only gives driving directions, so the other modes leave it out. */
export function appsForMode(apps: readonly DirectionsApp[], mode: TravelMode = "driving"): DirectionsApp[] {
  const unique = apps.filter((app, index) => apps.indexOf(app) === index);
  return mode === "driving" ? unique : unique.filter((app) => app !== "waze");
}

/**
 * The apps in the order to offer them. With a list of your own, that order
 * stands. Without one: Apple Maps first on an iPhone or iPad, Google Maps first
 * everywhere else, then the rest.
 */
export function orderApps(apps: readonly DirectionsApp[] | undefined, apple: boolean): DirectionsApp[] {
  if (apps) return apps.filter((app, index) => apps.indexOf(app) === index);
  return apple ? ["apple", "google", "waze"] : ["google", "apple", "waze"];
}

/** An iPhone or iPad, from what the browser says about itself. iPadOS 13 and later calls itself a Mac, but a Mac has no touch screen. */
export function prefersAppleMaps(environment: { userAgent?: string; platform?: string; maxTouchPoints?: number }): boolean {
  if (/iPhone|iPad|iPod/i.test(environment.userAgent ?? "")) return true;
  return environment.platform === "MacIntel" && (environment.maxTouchPoints ?? 0) > 1;
}

const encode = (pairs: readonly (readonly [string, string | undefined])[]) =>
  pairs
    .filter((pair): pair is readonly [string, string] => Boolean(pair[1]))
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
    .join("&");

const GOOGLE_MODE: Record<TravelMode, string> = { driving: "driving", walking: "walking", cycling: "bicycling", transit: "transit" };
// Apple Maps knows driving, walking and transit; for cycling it opens with its own default.
const APPLE_MODE: Partial<Record<TravelMode, string>> = { driving: "d", walking: "w", transit: "r" };

/** https://www.google.com/maps/dir/?api=1&destination=... Returns null when the destination cannot be used. */
export function buildGoogleMapsUrl(destination: DirectionsPlace, options: DirectionsOptions = {}): string | null {
  const to = placeQuery(destination);
  if (!to) return null;
  const from = options.origin ? placeQuery(options.origin) : null;
  return `https://www.google.com/maps/dir/?${encode([
    ["api", "1"],
    ["destination", to],
    ["origin", from ?? undefined],
    ["travelmode", GOOGLE_MODE[options.mode ?? "driving"]],
  ])}`;
}

/** https://maps.apple.com/?daddr=... Opens Maps on an iPhone, iPad and Mac. Returns null when the destination cannot be used. */
export function buildAppleMapsUrl(destination: DirectionsPlace, options: DirectionsOptions = {}): string | null {
  const to = placeQuery(destination);
  if (!to) return null;
  const from = options.origin ? placeQuery(options.origin) : null;
  // A destination given as bare coordinates has no name of its own, so the label goes in the query.
  const label = destination.address?.trim() ? undefined : destination.name?.trim();
  return `https://maps.apple.com/?${encode([
    ["daddr", to],
    ["saddr", from ?? undefined],
    ["dirflg", APPLE_MODE[options.mode ?? "driving"]],
    ["q", label],
  ])}`;
}

/** https://waze.com/ul?... Waze starts from the current position and drives. Returns null when the destination cannot be used. */
export function buildWazeUrl(destination: DirectionsPlace): string | null {
  const text = destination.address?.trim() ? placeQuery(destination) : null;
  if (text) return `https://waze.com/ul?${encode([["q", text], ["navigate", "yes"]])}`;
  const coordinates = coordinatesOf(destination);
  return coordinates ? `https://waze.com/ul?${encode([["ll", coordinates], ["navigate", "yes"]])}` : null;
}

/** The link for one app. */
export function buildDirectionsUrl(app: DirectionsApp, destination: DirectionsPlace, options: DirectionsOptions = {}): string | null {
  if (app === "apple") return buildAppleMapsUrl(destination, options);
  if (app === "waze") return buildWazeUrl(destination);
  return buildGoogleMapsUrl(destination, options);
}

/** Puts text on the clipboard. Where the Clipboard API is missing or blocked, a selected hidden field and the old copy command take over. */
export async function copyToClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "");
    Object.assign(area.style, { position: "fixed", top: "0", left: "0", width: "1px", height: "1px", opacity: "0", pointerEvents: "none" });
    document.body.append(area);
    const active = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    area.select();
    area.setSelectionRange(0, text.length);
    let copied = false;
    try {
      copied = document.execCommand("copy");
    } catch {
      copied = false;
    }
    area.remove();
    active?.focus({ preventScroll: true });
    return copied;
  }
}
